export function Delay({
  delay = {{delay}},
  duration = {{duration}},
  trigger = "{{trigger}}",
  accent = "{{accent}}",
  label = "{{label}}",
}) {
  return (
    <div data-trigger={trigger} style={{ position: "relative", width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", color: "#241430" }}>
      <div style={{ height: 3, background: "#24143033", maxWidth: 260, width: delay }} />
      <span className="dot" style={{ display: "block", width: 22, height: 22, borderRadius: 999, marginTop: -2, background: accent }} />
      <p style={{ margin: "12px 0 0", fontSize: 13, color: "#241430aa" }}>{label} &middot; waits {delay}ms, then runs for {duration}ms</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          [data-trigger="auto"] .dot { animation: mot-delay-run ${duration}ms ease-out ${delay}ms infinite; }
          [data-trigger="hover"] div:hover .dot { animation: mot-delay-run ${duration}ms ease-out ${delay}ms 1; }
          @keyframes mot-delay-run { 0% { transform: translateX(0); } 100% { transform: translateX(200px); } }
        }
      `}</style>
    </div>
  );
}
